def count_integers(lst):
    # Create an empty dictionary to store the counts of integers
    counts = {}

    # Loop through the list and add each integer to the dictionary with its count as 1
    for num in lst:
        if num not in counts:
            counts[num] = 0
        counts[num] += 1

    return counts
```

